def power(base, exp):
    if exp == 0:
        return 1
    if exp < 0:
        return 1 / power(base, -exp)
    return base * power(base, exp - 1)

print(power(2, 3))
print(power(3, 0))
print(power(2, -2))

def count_digits(n):
    if n < 0:
        n = -n
    if n < 10:
        return 1
    return 1 + count_digits(n // 10)

